from pathlib import Path
import json,hashlib,re,subprocess
p=Path('docs/rule_admission_review_evidence_20260911.json');e=json.loads(p.read_text(encoding='utf-8'))
changed=[name for name,h in e['fingerprints']['before'].items() if not Path(name).is_file() or hashlib.sha256(Path(name).read_bytes()).hexdigest()!=h]
ids=e['evidence_ids'];assert len(ids)==len(set(ids)); assert len(e['rule_reviews'])==80
span_errors=[]
