 if desc[r['span_start']:r['span_end']]!=r['source_text']:span_errors.append(r['id'])
path_errors=[]
for c in e['code_evidence']:
 lines=Path(c['path']).read_text(encoding='utf-8').splitlines()
 if not 1<=c['line']<=len(lines):path_errors.append(c['id'])
 if hashlib.sha256(Path(c['path']).read_bytes()).hexdigest()!=c['sha256']:path_errors.append(c['id']+' hash')
