 raw=Path(f).read_bytes();s=raw.decode('utf-8');lines=s.splitlines()
 for i,l in enumerate(lines,1):
  if l.rstrip()!=l:formats.append([f,i,'trailing_whitespace'])
 if not s.endswith('\n'):formats.append([f,'missing_final_newline'])
 if f.endswith('.md'):
  if sum(l.startswith('```') for l in lines)%2:formats.append([f,'unbalanced_code_fences'])
  for target in re.findall(r'\]\((D:/[^)]+)\)',s):
   target=re.sub(r':\d+$','',target)
   if not Path(target).is_file():link_errors.append(target)
  table=[]
  for i,l in enumerate(lines+[''],1):
   if l.startswith('|'):
    if table and l.count('|')!=table[0][1]:formats.append([f,i,'table_column_count'])
    table.append((i,l.count('|')))
   else:table=[]
 file_meta.append({'path':f,'bytes':len(raw),'lines':len(lines),'sha256':hashlib.sha256(raw).hexdigest()})
